// Block id → ghost tint family. Pure function; shared test vectors live in
// tests/tint_vectors.json (generated by scripts/gen_tint_vectors.py) so the
// Flutter app and this add-on always agree.

const COLOR_WORDS = new Set([
  'white', 'orange', 'magenta', 'light_blue', 'yellow', 'lime', 'pink',
  'gray', 'light_gray', 'cyan', 'purple', 'blue', 'brown', 'green', 'red',
  'black', 'silver',
]);

const WOODS = new Set([
  'oak', 'spruce', 'birch', 'jungle', 'acacia', 'dark_oak', 'mangrove',
  'cherry', 'bamboo', 'crimson', 'warped', 'cherry',
]);

function base(name) {
  return name.replace(/^minecraft:/, "");
}

export function ghostTintFor(bedrockId) {
  const n = base(bedrockId);
  if (n === "air" || n === "structure_void") return null;
  const parts = n.split("_");
  const head = parts[0];
  const tail = parts[parts.length - 1];

  if (n.includes("glass")) return "ghost_glass";
  if (n.includes("ice") || n.includes("snow")) return "ghost_white";
  if (n === "water" || n.includes("water")) return "ghost_blue";
  if (/glowstone|shroomlight|torch|lantern|campfire|end_rod|beacon|candle|redstone_lamp|sea_lantern/.test(n))
    return "ghost_glow";
  if (/^(coal|blackstone|obsidian|basalt|black)/.test(n)) return "ghost_black";
  if (/red_|crimson|nether_brick|magma|brick_block/.test(n) && !n.startsWith("red_sand"))
    return "ghost_red";
  if (/emerald|slime|moss|vine|kelp|seagrass|grass$/.test(n)) return "ghost_green";
  if (/lapis|diamond|blue/.test(n)) return "ghost_blue";
  if (/iron|gold|netherite|copper|raw_|chain|bars|anvil|hopper|pipe/.test(n))
    return "ghost_metal";
  if (/quartz|purpur|bone|end_stone|^calcite|^smooth_stone|concrete_powder$/.test(n))
    return head === "white" ? "ghost_white" : tintFromColorWord(n) ?? "ghost_white";
  if (/^(stone|cobble|granite|diorite|andesite|deepslate|tuff|bricks|stone_bricks)/.test(n))
    return "ghost_stone";
  if (/sand|gravel|clay|terracotta|hay|sponge|wool_stem/.test(n)) return "ghost_sand";

  if (WOODS.has(head) && !COLOR_WORDS.has(head)) {
    if (n.includes("leaves")) return "ghost_green";
    return "ghost_wood";
  }
  if (/^(log|planks|wood|fence|door|trapdoor|ladder|sign|bookshelf|noteblock|jukebox|chest|barrel|composter)/.test(n))
    return "ghost_wood";

  const cw = tintFromColorWord(n);
  if (cw) return cw;
  if (n.includes("concrete") || n.includes("wool") || n.includes("carpet") ||
      n.includes("terracotta"))
    return "ghost_gray";
  return "ghost_gray";
}

function tintFromColorWord(n) {
  const head = n.split("_")[0];
  switch (head) {
    case "white": return n.includes("concrete_powder") ? "ghost_sand" : "ghost_white";
    case "light_gray": case "silver": case "gray": return "ghost_gray";
    case "black": return "ghost_black";
    case "red": return "ghost_red";
    case "green": return "ghost_green";
    case "blue": return "ghost_blue";
    case "yellow": case "gold": return "ghost_glow";
    case "lime": return "ghost_green";
    case "pink": return "ghost_red";
    case "purple": case "magenta": return "ghost_blue";
    case "cyan": case "light_blue": return "ghost_blue";
    case "brown": return "ghost_wood";
    case "orange": return "ghost_red";
    default: return null;
  }
}

export function ghostBlockId(bedrockId) {
  const t = ghostTintFor(bedrockId);
  return t ? `s3d:${t}` : null;
}

export const GHOST_BLOCKS = [
  "ghost_white", "ghost_gray", "ghost_black", "ghost_wood", "ghost_stone",
  "ghost_sand", "ghost_glass", "ghost_red", "ghost_green", "ghost_blue",
  "ghost_metal", "ghost_glow",
].map((t) => `s3d:${t}`);
